use sdl3_sys::scancode::*;

pub fn rs_key_from_scancode(sc: SDL_Scancode) -> i32 {
    match sc {
        SDL_SCANCODE_SPACE => b' ' as i32,
        SDL_SCANCODE_APOSTROPHE => b'\'' as i32,
        SDL_SCANCODE_COMMA => b',' as i32,
        SDL_SCANCODE_MINUS => b'-' as i32,
        SDL_SCANCODE_PERIOD => b'.' as i32,
        SDL_SCANCODE_SLASH => b'/' as i32,
        SDL_SCANCODE_0 => b'0' as i32,
        SDL_SCANCODE_1 => b'1' as i32,
        SDL_SCANCODE_2 => b'2' as i32,
        SDL_SCANCODE_3 => b'3' as i32,
        SDL_SCANCODE_4 => b'4' as i32,
        SDL_SCANCODE_5 => b'5' as i32,
        SDL_SCANCODE_6 => b'6' as i32,
        SDL_SCANCODE_7 => b'7' as i32,
        SDL_SCANCODE_8 => b'8' as i32,
        SDL_SCANCODE_9 => b'9' as i32,
        SDL_SCANCODE_SEMICOLON => b';' as i32,
        SDL_SCANCODE_EQUALS => b'=' as i32,
        SDL_SCANCODE_A => b'A' as i32,
        SDL_SCANCODE_B => b'B' as i32,
        SDL_SCANCODE_C => b'C' as i32,
        SDL_SCANCODE_D => b'D' as i32,
        SDL_SCANCODE_E => b'E' as i32,
        SDL_SCANCODE_F => b'F' as i32,
        SDL_SCANCODE_G => b'G' as i32,
        SDL_SCANCODE_H => b'H' as i32,
        SDL_SCANCODE_I => b'I' as i32,
        SDL_SCANCODE_J => b'J' as i32,
        SDL_SCANCODE_K => b'K' as i32,
        SDL_SCANCODE_L => b'L' as i32,
        SDL_SCANCODE_M => b'M' as i32,
        SDL_SCANCODE_N => b'N' as i32,
        SDL_SCANCODE_O => b'O' as i32,
        SDL_SCANCODE_P => b'P' as i32,
        SDL_SCANCODE_Q => b'Q' as i32,
        SDL_SCANCODE_R => b'R' as i32,
        SDL_SCANCODE_S => b'S' as i32,
        SDL_SCANCODE_T => b'T' as i32,
        SDL_SCANCODE_U => b'U' as i32,
        SDL_SCANCODE_V => b'V' as i32,
        SDL_SCANCODE_W => b'W' as i32,
        SDL_SCANCODE_X => b'X' as i32,
        SDL_SCANCODE_Y => b'Y' as i32,
        SDL_SCANCODE_Z => b'Z' as i32,
        SDL_SCANCODE_LEFTBRACKET => b'[' as i32,
        SDL_SCANCODE_BACKSLASH => b'\\' as i32,
        SDL_SCANCODE_RIGHTBRACKET => b']' as i32,
        SDL_SCANCODE_GRAVE => b'`' as i32,
        SDL_SCANCODE_ESCAPE => rs::rsESC,
        SDL_SCANCODE_RETURN => rs::rsENTER,
        SDL_SCANCODE_TAB => rs::rsTAB,
        SDL_SCANCODE_BACKSPACE => rs::rsBACKSP,
        SDL_SCANCODE_INSERT => rs::rsINS,
        SDL_SCANCODE_DELETE => rs::rsDEL,
        SDL_SCANCODE_RIGHT => rs::rsRIGHT,
        SDL_SCANCODE_LEFT => rs::rsLEFT,
        SDL_SCANCODE_DOWN => rs::rsDOWN,
        SDL_SCANCODE_UP => rs::rsUP,
        SDL_SCANCODE_PAGEUP => rs::rsPGUP,
        SDL_SCANCODE_PAGEDOWN => rs::rsPGDN,
        SDL_SCANCODE_HOME => rs::rsHOME,
        SDL_SCANCODE_END => rs::rsEND,
        SDL_SCANCODE_CAPSLOCK => rs::rsCAPSLK,
        SDL_SCANCODE_SCROLLLOCK => rs::rsSCROLL,
        SDL_SCANCODE_NUMLOCKCLEAR => rs::rsNUMLOCK,
        SDL_SCANCODE_PAUSE => rs::rsPAUSE,
        SDL_SCANCODE_F1 => rs::rsF1,
        SDL_SCANCODE_F2 => rs::rsF2,
        SDL_SCANCODE_F3 => rs::rsF3,
        SDL_SCANCODE_F4 => rs::rsF4,
        SDL_SCANCODE_F5 => rs::rsF5,
        SDL_SCANCODE_F6 => rs::rsF6,
        SDL_SCANCODE_F7 => rs::rsF7,
        SDL_SCANCODE_F8 => rs::rsF8,
        SDL_SCANCODE_F9 => rs::rsF9,
        SDL_SCANCODE_F10 => rs::rsF10,
        SDL_SCANCODE_F11 => rs::rsF11,
        SDL_SCANCODE_F12 => rs::rsF12,
        SDL_SCANCODE_KP_0 => rs::rsPADINS,
        SDL_SCANCODE_KP_1 => rs::rsPADEND,
        SDL_SCANCODE_KP_2 => rs::rsPADDOWN,
        SDL_SCANCODE_KP_3 => rs::rsPADPGDN,
        SDL_SCANCODE_KP_4 => rs::rsPADLEFT,
        SDL_SCANCODE_KP_5 => rs::rsPAD5,
        SDL_SCANCODE_KP_6 => rs::rsPADRIGHT,
        SDL_SCANCODE_KP_7 => rs::rsPADHOME,
        SDL_SCANCODE_KP_8 => rs::rsPADUP,
        SDL_SCANCODE_KP_9 => rs::rsPADPGUP,
        SDL_SCANCODE_KP_PERIOD => rs::rsPADDEL,
        SDL_SCANCODE_KP_DIVIDE => rs::rsDIVIDE,
        SDL_SCANCODE_KP_MULTIPLY => rs::rsTIMES,
        SDL_SCANCODE_KP_MINUS => rs::rsMINUS,
        SDL_SCANCODE_KP_PLUS => rs::rsPLUS,
        SDL_SCANCODE_KP_ENTER => rs::rsPADENTER,
        SDL_SCANCODE_LSHIFT => rs::rsLSHIFT,
        SDL_SCANCODE_LCTRL => rs::rsLCTRL,
        SDL_SCANCODE_LALT => rs::rsLALT,
        SDL_SCANCODE_LGUI => rs::rsLWIN,
        SDL_SCANCODE_RSHIFT => rs::rsRSHIFT,
        SDL_SCANCODE_RCTRL => rs::rsRCTRL,
        SDL_SCANCODE_RALT => rs::rsRALT,
        SDL_SCANCODE_RGUI => rs::rsRWIN,

        _ => rs::rsNULL,
    }
}
